import{z as s,x as i,o as t,c as p,q as n,j as r,D as e,d as a,s as o,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"容量治理","description":"","frontmatter":{"title":"容量治理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-capacity-governance.md","filePath":"quant/sl-capacity-governance.md","lastUpdated":1791063341000}'),d={name:"quant/sl-capacity-governance.md"};function c(m,E,C,u,h,D){const B=i("Mermaid");return t(),p("div",null,[E[2]||(E[2]=n('<h1 id="容量治理" tabindex="-1">容量治理 <a class="header-anchor" href="#容量治理" aria-label="Permalink to &quot;容量治理&quot;">​</a></h1><div class="epigraph"><p>规模不是业绩的中性放大器：资金自己参与价格形成，规模本身改变收益的生成过程。</p><footer>—— 据 Perold 与 Salomon, Financial Analysts Journal, 1991 整理</footer></div><p><a href="/quant/sl-versioning-approval">上一课</a>把批准写成对声明的一致性核对，声明里分量最重的一项是容量曲线。研究侧容量怎么算——冲击核、过零点、发表后缩水——已在<a href="/quant/strategy-capacity-decay">策略容量与衰减</a>写清；本课写它的治理面：容量从研究报告里的一个数字，变成带限额、触发器与扩容流程的治理对象。衰减怎么治是下一课，本课只管「跑多大」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>容量声明最常见的死法是「批准后无人再读」：审批时引用了曲线，募资与配置却在另一条线上推进，规模涨过零点时没有任何机制报警。反过来也有对面的错：把容量当成上线前的门槛，上线后再也不看拥挤相关与参与率的漂移——而自身交易会改写后续 IC，<a href="/quant/strategy-capacity-decay">容量课的机制</a>不因上线而失效。缺口因此是双侧的：扩容没有流程，占满没有触发器。治理要回答的不是「容量是多少」，而是「谁在什么条件下允许把规模推到哪一档，超了之后先发生什么」。</p><p><span class="marginnote">直觉类比：把市场想成一口深浅固定的水缸，你的买单是从缸里舀水。舀一杯水位不动；舀到大用时，你自己的动作已经把水位压低了，后面每一勺都要为前面舀掉的付出更深的管子。容量治理就是提前约定「最多舀到哪条刻度线」，以及超线时谁来关阀门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>台账容量字段的活用分三层。<strong>声明层</strong>：过零曲线 \\(\\mu_{\\mathrm{net}}(A,h)\\)、参与率上限、冲击核半衰期与拥挤态假设，缺一项即不可审计，审计时退回而不是替作者补。<strong>限额层</strong>：硬限额写进执行层——单日参与率、名义敞口、换市场前重检——超限是拒单不是警告；软预算走月度复审，读参与率实绩与同策略生态位的滚动相关。<strong>流程层</strong>：扩容即新版本，按 \\(\\mu_{\\mathrm{net}}(A)\\) 分档放大、每档设观察期，与<a href="/quant/paper-to-live-staging">三级台阶</a>的放大口径一致；缩容不需审批——监测穿带即预授权降杠杆。扩与缩的不对称要钉死：扩容错误的损失是线性的，缩容错误的损失只是少赚，所以两个方向的门槛必须不同。</p><p><span class="marginnote">术语翻译：硬限额是写进执行系统的「护栏」，超了直接拒单，不等人点头；软预算是月度复审桌上的「体检指标」，超了先讨论再行动。前者防瞬间事故，后者防缓慢漂移——只有体检没有护栏，崩起来来不及开会；只有护栏没有体检，会死得莫名其妙。</span></p>',9)),(t(),r(l,null,{default:e(()=>[o(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E6%89%A9%E5%AE%B9%E8%AF%B7%E6%B1%82%EF%BC%9A%E7%9B%AE%E6%A0%87%E8%A7%84%E6%A8%A1%22%5D%20--%3E%20CURVE%7B%22%E8%90%BD%E5%9C%A8%E5%B7%B2%E6%89%B9%E5%87%86%E5%AE%B9%E9%87%8F%E6%A1%A3%E5%86%85%3F%22%7D%0A%20%20CURVE%20--%3E%7C%E6%98%AF%7C%20STAGE%5B%22%E5%88%86%E6%A1%A3%E6%94%BE%E5%A4%A7%EF%BC%9A%E8%A7%82%E5%AF%9F%E6%9C%9F%E4%B8%8E%E7%9B%91%E6%B5%8B%E7%85%A7%E5%B8%B8%22%5D%0A%20%20CURVE%20--%3E%7C%E5%90%A6%7C%20NEWVER%5B%22%E6%96%B0%E7%89%88%E6%9C%AC%E4%B8%8E%E5%AE%A1%E6%89%B9%EF%BC%9A%E6%9B%B4%E6%96%B0%E5%AE%B9%E9%87%8F%E5%A3%B0%E6%98%8E%22%5D%0A%20%20STAGE%20--%3E%20MON%5B%22%E6%9C%88%E5%BA%A6%E5%A4%8D%E5%AE%A1%EF%BC%9A%E5%8F%82%E4%B8%8E%E7%8E%87%E5%AE%9E%E7%BB%A9%E4%B8%8E%E6%8B%A5%E6%8C%A4%E7%9B%B8%E5%85%B3%22%5D%0A%20%20NEWVER%20--%3E%20MON%0A%20%20MON%20--%3E%7C%E7%A9%BF%E9%A2%84%E7%AE%97%E5%B8%A6%7C%20CUT%5B%22%E9%99%8D%E6%9D%A0%E6%9D%86%EF%BC%9A%E7%9B%91%E6%B5%8B%E9%A2%84%E6%8E%88%E6%9D%83%EF%BC%8C%E4%B8%8D%E9%9C%80%E5%AE%A1%E6%89%B9%22%5D%0A%20%20MON%20--%3E%7C%E5%B8%A6%E5%86%85%7C%20KEEP%5B%22%E7%BB%B4%E6%8C%81%E5%B9%B6%E8%AE%B0%E5%BD%95%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("容量治理之所以必须是治理而不是研究结论，根源在三个耦合。其一，容量是状态的函数：拥挤态变了，同一条曲线的过零点就变了，所以声明要随"),A("a",{href:"/quant/live-drift-monitor"},"拥挤相关预算带"),a("联动复审，而不是一年一签。其二，多策略共享冲击核：两个策略各自的参与率都在限内，加总却可能占满同一批流动性，因此参与率要策略层与组合层双记账，组合层限额归风险团队写入。其三，加权口径的诚实性：把宇宙悄悄换成等权微盘，容量曲线可以好看一倍以上，Hou–Xue–Zhang 的复制缩水就是这类口径游戏的样本证据——治理上，声明宇宙与实盘宇宙不一致，按违规持仓处置，不做学术讨论。")],-1)),(t(),r(l,null,{default:e(()=>[o(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SA%5B%22%E7%AD%96%E7%95%A5%20A%20%E4%BA%A4%E6%98%93%22%5D%20--%3E%20LSA%5B%22%E7%AD%96%E7%95%A5%E5%B1%82%E8%AE%B0%E8%B4%A6%EF%BC%9A%E5%8F%82%E4%B8%8E%E7%8E%87%203%25%22%5D%0A%20%20SB%5B%22%E7%AD%96%E7%95%A5%20B%20%E4%BA%A4%E6%98%93%22%5D%20--%3E%20LSB%5B%22%E7%AD%96%E7%95%A5%E5%B1%82%E8%AE%B0%E8%B4%A6%EF%BC%9A%E5%8F%82%E4%B8%8E%E7%8E%87%203%25%22%5D%0A%20%20LSA%20--%3E%20AGG%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E5%8A%A0%E6%80%BB%22%5D%0A%20%20LSB%20--%3E%20AGG%0A%20%20AGG%20--%3E%20POOL%5B%22%E5%85%B1%E4%BA%AB%E5%90%8C%E4%B8%80%E6%89%B9%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20POOL%20--%3E%20TOT%5B%22%E7%BB%84%E5%90%88%E5%8F%82%E4%B8%8E%E7%8E%87%EF%BC%9A%E9%80%BC%E8%BF%91%E4%B8%8A%E9%99%90%22%5D%0A%20%20TOT%20--%3E%20LIMIT%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E9%99%90%E9%A2%9D%EF%BC%9A%E9%A3%8E%E9%99%A9%E5%9B%A2%E9%98%9F%E5%86%99%E5%85%A5%E6%89%A7%E8%A1%8C%E5%B1%82%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">一个常用的粗校验：若声明的参与率、核半衰期与拥挤态三项缺一，容量曲线不可审计；审计动作是退回重写，而不是替作者补假设——补出来的曲线会在最需要它的时刻失真。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>容量曲线的校准只能用自己的成交做：别人的执行数据里没有你的冲击，借来的半衰期会把容量估错一个量级，校准过期要触发复审。本课不写冲击模型的谱系与执行细节——那是交易执行深钻的主题；也不重算过零点——数学在<a href="/quant/strategy-capacity-decay">容量与衰减</a>里。容量治理管的是「自己吃自己」的速度上限；别人吃掉它的速度，是下一课衰减治理的对象，两课共享同一条拥挤相关预算带，但读数与动作不同。</p><p><span class="marginnote">常见误区：初学者容易以为容量是策略的固定属性，像发动机排量一样出厂即定。实际上它随拥挤态、对手行为和自己的历史成交而变——别人进场吃同一批信号，你的过零点就前移。所以容量曲线要联动复审，批准一次用十年是治理上的定时炸弹。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容量治理分声明、限额、流程三层：曲线可审计、硬限进执行层、扩容即新版本。</li><li>扩容与缩容门槛不对称：扩要审批与观察期，缩由监测预授权。</li><li>参与率在策略层与组合层双记账；声明宇宙与实盘宇宙不一致按违规处置。</li><li>拥挤相关预算带联动复审，容量声明不是一年一签的静态数字。</li><li>出处：Perold–Salomon, <em>FAJ</em>, 1991；容量曲线与冲击核见<a href="/quant/strategy-capacity-decay">策略容量与衰减</a>；发表后缩水见 McLean–Pontiff, <em>JF</em>, 2016 与 Hou–Xue–Zhang, <em>RFS</em>, 2020。</li></ul>',6))])}const g=s(d,[["render",c]]);export{F as __pageData,g as default};
